CH = {'observe': (1, 'Observe'), 'decide': (4, 'Decide'), 'represent': (2, 'Represent'), 'collaborate': (3, 'Collaborate'), 'other': (None, None)}
P = [
 dict(id='survival', num='01', fam='observe', famlabel='Observation & experimental design', title='Budget-constrained active learning',
  full='Budget-constrained Active Learning to Effectively De-censor Survival Data', status='Under review · ICLR 2027 · arXiv 2025', kind='paper',
  authors='<b>Ali Parsaee</b>, Bei Jiang, Zachary Friggstad, Russell Greiner', note='MSc thesis work, University of Alberta',
  links=[('Read the paper (arXiv)', 'https://arxiv.org/abs/2510.12144')], question='Which patients should we follow, and for how long?',
  point='When follow-up is expensive, spend it on the patients and durations that teach the model the most per unit of cost, even though a follow-up may end in “not yet”.',
  problem='Survival data contain censored patients: we only know they were event-free up to some time. Following them up costs time and money, and the answer is often partial. A follow-up can reveal the event, or only move the “event-free until” date. Standard active learning assumes every query returns a complete label.',
  did='We extended budgeted active learning to censored data. A query buys a follow-up of a chosen length for a chosen patient and can return a partial label. The acquisition rule extends BatchBALD to these partial answers and to unequal costs.',
  found=['Bounds and time complexity asymptotically equivalent to BatchBALD, the standard batch active learning method.', 'Across several real survival datasets, the method performed better than the other approaches we compared.'],
  caption='Simplified illustration on simulated patients. Here “information” is about each patient’s own event time; in the paper it is information about the model, as in BatchBALD.',
  deeper='A censored patient (3 years, censored) can be probed for one more year. The result is either an event at, say, 3.2 years, or a new censoring time of 4 years. The learner scores every patient and probe depth by the expected information it buys, divided by its cost, and spends the budget greedily. Choosing batches this way is a maximum-coverage problem, which is why greedy selection comes with an approximation guarantee.'),
 dict(id='causal', num='02', fam='decide', famlabel='Evidence & decisions', title='Censor-aware causal experiments',
  full='When Does Censor Awareness Help Survival-Policy Identification?', status='Research manuscript · under review', kind='manuscript',
  authors='<b>Ali Parsaee</b> and collaborators', note='', links=[], question='Which experiment helps us choose a treatment policy?',
  point='When outcomes can stay censored, what matters is how often events are observed among the patients who can tell the candidate policies apart, not the trial’s overall censoring rate.',
  problem='A trial that must choose a treatment rule observes event times, or only that no event happened before follow-up ended. Pure-exploration theory tells us how to allocate a budget when outcomes arrive immediately, and adaptive survival trials handle censoring when the goal is estimation. Choosing a policy under censoring sits between the two.',
  did='The project studies how to allocate recruitment across patient groups and randomized treatments so that the best policy from a candidate set is identified with as little budget as possible, when outcomes may remain censored.',
  found=['The results are under review and will be posted when the paper is public.'],
  caption='Illustration of the question on simulated patients. No results from the manuscript are shown.',
  deeper='The target is a final policy recommendation, not every model parameter. Information about a parameter matters only if it changes which policy looks best.'),
 dict(id='generalization', num='03', fam='represent', famlabel='Representation & learning', title='Generalization versus memorization',
  full='Generalization versus memorization: exact costs in small networks', status='Research manuscript · under review', kind='manuscript',
  authors='<b>Ali Parsaee</b>', note='First-author research project', links=[], question='When is learning a pattern cheaper than remembering examples?',
  point='A network that encodes a rule can be far cheaper than one that memorizes examples. Whether training actually finds the cheap solution is a separate question.',
  problem='Networks can fit their training examples long before they generalize. One explanation is that training with weight decay prefers small-weight solutions, and rules tend to need smaller weights than lookup tables. That turns three questions into one: how cheap a good solution can be, whether one exists at a given size, and whether gradient descent reaches it.',
  did='The project computes exact representation costs in small ReLU networks on structured tasks such as parity, then asks separately whether optimization reaches the cheapest solutions.',
  found=['The results are under review and will be posted when the paper is public.'],
  caption='Two hand-built networks that both classify parity correctly. Costs are exact for these constructions; they are not the optimum computed in the manuscript.',
  deeper='This is bounded theoretical work on small networks and synthetic tasks, not a complete explanation of generalization in deep networks.'),
 dict(id='crowds', num='04', fam='collaborate', famlabel='Collective intelligence', title='Wisdom of the Machines',
  full='Wisdom of the Machines: Exploring Collective Intelligence in LLM Crowds', status='AAMAS 2026 · Paphos, Cyprus', kind='paper',
  authors='Yashar Talebirad*, <b>Ali Parsaee</b>*, Vishwajeet Ohal, Amirhossein Nadiri, Csongor Szepesvári, Yash Mouje, Eden Redman', note='* equal contribution',
  links=[('Read the paper', 'https://openreview.net/forum?id=fxqroxvUhk')], question='What can a diverse crowd of models know together?',
  point='A crowd of language models is wise when its members are different models. Sampling one model many times repeats that model’s mistakes.',
  problem='Averaging many independent human guesses often beats any individual: the “wisdom of crowds”. Large language models can produce many guesses cheaply, but it was unclear how to form a useful crowd from them.',
  did='We compared two sources of diversity on vision-based estimation tasks: response diversity, from sampling one model at several temperatures, and model diversity, from asking different models. The datasets were people’s height and weight from photos, small objects with known weights, and Amazon products with their prices.',
  found=['Aggregating temperature-0 answers from a diverse set of models was the most effective strategy, and it outperformed any single model.', 'Temperature-induced diversity gave no significant benefit while increasing inference cost.', 'The median of deterministic answers from several models beat 68% of individual guesses on average.', 'Context helped where it was directly informative, such as product titles for price estimation.'],
  caption='Simulated crowd: each model has its own bias, and temperature adds noise around it. The 68% figure is from the paper.',
  deeper='The median is robust to a few wild answers, which matters because language models occasionally misread an image badly. Model diversity works because different models were trained differently and so err in different directions; their errors partly cancel.'),
 dict(id='memory', num='05', fam='represent', famlabel='Representation & learning', title='Hierarchical memory for language agents',
  full='Toward a Theory of Hierarchical Memory for Language Agents', status='MemAgents workshop · ICLR 2026', kind='paper',
  authors='Yashar Talebirad, <b>Ali Parsaee</b>, Csongor Y. Szepesvari, Amirhossein Nadiri, Osmar Zaiane', note='Joint first author',
  links=[('Read the paper (arXiv)', 'https://arxiv.org/abs/2603.21564')], question='How much detail is worth keeping as information ages?',
  point='Every hierarchical memory system can be described with three operators: extract atomic units, coarsen them into groups with representatives, and traverse the hierarchy under a token budget.',
  problem='Long-context and agentic systems keep adding hierarchical memory to get around context limits. Each system is presented as its own design, with no shared language for comparing the choices they make.',
  did='We proposed a unifying theory. Extraction (α) maps raw data to atomic units. Coarsening (C) groups units and gives each group a representative. Traversal (τ) chooses which units enter the context for a query and a budget.',
  found=['A “self-sufficiency spectrum” for representatives: summaries that can stand in for their group, versus keys that only point to it.', 'Where a system sits on that spectrum constrains which traversal strategies work: coarsening and traversal must be chosen together.', 'The decomposition describes eleven existing systems, spanning document hierarchies, conversational memory and agent execution traces.'],
  caption='Illustration of the three operators on a small hierarchy.',
  deeper='Complex agentic tasks involve three coupled hierarchies: stored knowledge, the agent’s own traces, and the task’s decomposition. How they should align is an open question the paper raises.'),
 dict(id='compute', num='06', fam='collaborate', famlabel='Collective intelligence', title='Spend Compute Where Errors Propagate',
  full='Spend Compute Where Errors Propagate', status='Under review', kind='manuscript',
  authors='<b>Ali Parsaee</b>, Yashar Talebirad', note='First author', links=[], question='Where should another unit of computation go?',
  point='When a hard problem is split into dependent sub-problems, a mistake high in the structure corrupts everything built on it. Extra computation should go where errors propagate.',
  problem='AI systems often break a problem into a plan, sub-plans and steps, sample several answers at each step, and aggregate them by voting or with a verifier. In common practice every step gets the same number of samples, whatever depends on it.',
  did='The project formalizes the expected amount of corrupted work and derives how a fixed sampling budget should be divided across the dependency structure.',
  found=['The results are under review and will be posted when the paper is public.'],
  caption='Simulation of the idea on small dependency trees. Sub-problem error falls with more samples; a wrong answer corrupts everything below it.',
  deeper='Whether structure-aware allocation helps depends on how errors are scored. If any single mistake ruins the whole answer, the structure stops mattering; if partial work keeps its value, it matters a great deal.'),
 dict(id='personalization', num='07', fam='decide', famlabel='Evidence & decisions', title='Is personalization worth it?',
  full='When Is a Learned Treatment Policy Worth Personalizing?', status='Research manuscript', kind='manuscript',
  authors='<b>Ali Parsaee</b>, with Tina Sami', note='', links=[], question='Does an individualized rule actually improve the decision?',
  point='A learned treatment rule can beat observed practice only because one treatment for everyone would already beat it. The gain from personalizing is what is left after that.',
  problem='Learned treatment policies are usually compared with what clinicians actually did. That comparison mixes two questions: could practice improve by choosing one action for everyone, and does tailoring the action to each patient add anything beyond that?',
  did='The project separates the two gains, evaluates learned policies against the better of the two comparators, and allows the evaluation to withhold a verdict when the evidence or the diagnostics cannot support one.',
  found=['The results are under review and will be posted when the paper is public.'],
  caption='Simulated outcomes. Sliders change the average benefit of one treatment, how much that benefit varies, and the study size.',
  deeper='A finding about one learned rule is not a claim about the best possible personalized policy. The quantity of interest is the improvement of the tested rule over a single rule for everyone.'),
 dict(id='media', num='08', fam='observe', famlabel='Observation & experimental design', title='Learning what to grow',
  full='A data-driven evaluation of optimization techniques in cell culture media', status='Bioinformatics · 2026', kind='paper',
  authors='<b>Ali Parsaee</b>, Miranda Stahn, Arian Amirvaresi, Reza Ovissipour, David Staszak', note='First author',
  links=[('Read the paper', 'https://doi.org/10.1093/bioinformatics/btag607'), ('Code and data', 'https://github.com/Amii-Applied-AI/amii-cell-ag-tools/tree/main/active-learning-for-cell-media')],
  question='Which experiment buys the most improvement in cell culture?',
  point='On real measured cell-culture formulations, Bayesian optimization with a Gaussian process found good media in fewer experiments than classical designs or random search.',
  problem='Optimizing a growth medium for cultivated meat is slow and expensive: every formulation has to be made and measured. Earlier comparisons of optimizers relied mostly on simulations, which left labs without evidence on which strategy to adopt.',
  did='We built two benchmark protocols and ran them on six published cell-culture datasets. In “Hide-the-Label”, an optimizer starts with a partial view and reveals hidden formulations one at a time or in batches, like costly lab measurements. In “Open Race”, methods compete under a fixed evaluation budget. We tested four surrogate models (Gaussian process, random forest, neural network, Bayesian neural network), two difficulty regimes, and batch sizes from 1 to 20.',
  found=['Gaussian-process Bayesian optimization was consistently the most sample-efficient strategy.', 'Its advantage narrowed but remained under added noise and multiple peaks.', 'Optimizers built on more complex surrogates (deeper networks, adaptive ensembles) did worse, not better, on the harder landscapes.'],
  caption='Simulated landscape in the spirit of the Hide-the-Label protocol. The finding about Gaussian-process optimization is the paper’s.',
  deeper='The paper also sets out criteria for choosing benchmark datasets and how to draw statistically robust conclusions when measurements are biased and heterogeneous, ending with a roadmap for choosing a strategy in practice.'),
 dict(id='loopbench', num='09', fam='collaborate', famlabel='Collective intelligence', title='LoopBench',
  full='LoopBench: Discovering Emergent Symmetry Breaking Strategies with LLM Swarms', status='Preprint · arXiv 2025', kind='paper',
  authors='<b>Ali Parsaee</b>, Yashar Talebirad, Csongor Szepesvári, Vishwajeet Ohal, Eden Redman', note='First author',
  links=[('Read the paper (arXiv)', 'https://arxiv.org/abs/2512.13713')], question='What can emerge from a swarm’s interactions?',
  point='Identical agents that each act sensibly can lock into an endless loop together. Escaping it takes an agent that reflects on its own history and changes its rule.',
  problem='Language models are increasingly used as autonomous agents, but little is known about whether independent agents, each with a local view, can invent the strategies needed to coordinate without a central controller.',
  did='We built a benchmark around colouring odd rings (3, 5 and 11 nodes) with two colours. A perfect colouring is impossible, and simple greedy agents oscillate forever. Each node is an LLM agent that sees its local history and can pass a short note of strategy to its future self.',
  found=['Advanced reasoning models (O3) devised strategies to escape the deadlock. On the 5-node ring O3 scored 57.5% proximity to the best colouring with 100% stability.', 'GPT-4.1 Nano agents scored 4.4% proximity on the same ring.', 'Classical heuristics struggled, revealing a measurable reasoning gap between classes of models.'],
  caption='Simulated agents with hand-written rules. Benchmark numbers are from the paper.',
  deeper='The benchmark tests meta-cognitive reasoning: thinking narrowly leads to deadlock, and the solution only appears when an agent steps back and questions its own rule.'),
 dict(id='signals', num='13', fam='collaborate', famlabel='Collective intelligence', title='From Signals to Structure',
  full='From Signals to Structure: How Memory Architecture Drives Language Emergence in LLM Agents', status='ALIFE 2026', kind='paper',
  authors='Yashar Talebirad, Eden Redman, <b>Ali Parsaee</b>, Osmar R. Zaïane', note='',
  links=[('Read the paper', 'https://doi.org/10.1162/isal.a.1045'), ('arXiv', 'https://arxiv.org/abs/2607.00233')], question='How does memory shape the emergence of language?',
  point='Whether two agents invent a stable shared language depends more on how they remember than on how much they can say.',
  problem='In a Lewis signalling game, a sender sees a target among several objects and sends a signal; a receiver must pick the target from the signal alone. With no agreed meanings, any consistent success means the pair has invented a small language.',
  did='We compared five memory architectures for LLM agents across channel sizes, from stateless agents with a rolling context window to agents with a persistent private notebook.',
  found=['Memory architecture mattered more than channel capacity.', 'Agents with a persistent notebook coordinated most reliably: 0.867 ± 0.023 at a capacity of 25 signals.', 'Stateless agents peaked at moderate capacity, then degraded as the vocabulary outgrew their window.', 'Capacity equal to the number of objects (8), which an information-bottleneck argument predicts as optimal, was instead a fragile point.'],
  caption='A toy version of the game with simple learning agents, not LLMs. The accuracy figures quoted are the paper’s.',
  deeper='Notebooks have their own failure mode: agents sometimes revise an established mapping in the middle of a game, which breaks the convention the partner relies on.'),
 dict(id='communication', num='14', fam='collaborate', famlabel='Collective intelligence', title='Memory Is Communication',
  full='Memory Is Communication: The Frontier Between Remembering and Signaling', status='ALIFE 2026 · late-breaking abstract', kind='paper',
  authors='Yashar Talebirad, Eden Redman, <b>Ali Parsaee</b>, Osmar R. Zaïane', note='',
  links=[('Read the abstract (arXiv)', 'https://arxiv.org/abs/2608.17053')], question='What changes when information is remembered or exchanged?',
  point='An agent can get the information for a decision from its own past or from a peer. Under limits on both, the two trade off along a frontier.',
  problem='Cooperative agents act from partial views with limited memory and limited bandwidth. Retained history can carry what a peer would otherwise have to say, and a message can supply what memory lacks.',
  did='We defined the remembering–signalling frontier: the efficient boundary of memory and message rates that reach a given performance. We hypothesize that an agent needs less communication when its history reduces task loss more.',
  found=['In preliminary referential games, targets that repeated came with shorter successful messages.', 'Predictability from a hidden cyclic rule did not shorten messages.', 'This is a hypothesis-stage abstract; the paper outlines experiments to estimate the frontier.'],
  caption='Exact message requirements for a simple process where the target repeats with some probability.',
  deeper='The idea connects to rate-distortion theory and to Wyner–Ziv coding, where information already at the receiver lowers the bits needed to reach an error target.'),
 dict(id='cooperative', num='15', fam='collaborate', famlabel='Collective intelligence', title='Cooperative observation',
  full='Toward Personal Intelligence Through Cooperative Observation', status='PILA workshop · KDD 2026', kind='paper',
  authors='Yashar Talebirad, Osman Jime, <b>Ali Parsaee</b>, Eden Redman, Yongbin Kim, Osmar R. Zaïane', note='',
  links=[('Read the paper (arXiv)', 'https://arxiv.org/abs/2608.17128')], question='How can agents observe usefully together?',
  point='What a personal AI can observe depends on whether its help earns continued access: usefulness, trust and access form one loop.',
  problem='A personal AI needs a model of its user’s goals and commitments, and that model is limited by what it can observe. More observation does not help by itself: the system must select and compress, and the user decides what it may see.',
  did='We framed this as cooperative observation: the system acts on a partial model, the user evaluates the result, and that evaluation shapes what the system may observe next. We report a preliminary single-user account from Organizm, a prototype used over six months.',
  found=['A framework connecting observation quality, usefulness, trust and future access.', 'Evaluation directions for measuring how observation quality shapes personal AI.', 'A six-month single-user deployment record; controlled multi-user studies are needed to test causes.'],
  caption='Illustrative dynamics of the loop, not data.',
  deeper='Useful, inspectable behaviour gives users a reason to keep or widen the channel; failures lead them to correct it, narrow it, revoke it or abandon the system.'),
 dict(id='crohns', num='19', fam='decide', famlabel='Evidence & decisions', title='Predicting bowel resection in Crohn’s disease',
  full='Machine learning predicts first elective bowel resection in newly diagnosed pediatric Crohn disease patients', status='Journal of Pediatric Surgery · 2026', kind='paper',
  authors='Ricardo G. Suarez Suarez, <b>Ali Parsaee</b>, Shahzaib Ahmed, … Russell Greiner, Eytan Wine, and the Canadian Children IBD Network', note='Second of 22 authors',
  links=[('Read the paper', 'https://doi.org/10.1016/j.jpedsurg.2026.163488')], question='Useful prediction from incomplete clinical observations.',
  point='Instead of one risk score, each child gets a whole curve: the probability of a first bowel resection at every future time.',
  problem='Children with Crohn disease need surgery more often than adults. Existing risk scores do not give an individual child’s probability of surgery over time.',
  did='We learned models that predict individual survival distributions from clinical and laboratory data in a prospective national cohort of 934 children. Two SuperLearners used baseline data alone, or baseline plus week-10 data, each selecting among survival models by cross-validation.',
  found=['Predicted surgery times were off by 755 days on average with baseline data and 840 days with week-10 data added.', 'The features the models selected matched earlier clinical studies: penetrating and stricturing disease, and the perianal modifier.'],
  caption='Illustrative curves, not the paper’s fitted model. The error figures are the paper’s.',
  deeper='Many children had not had surgery by the end of follow-up, so their outcomes are censored. Individual survival distributions use those children too, rather than discarding them.'),
 dict(id='radiation', num='20', fam='decide', famlabel='Evidence & decisions', title='Risk after radiation therapy',
  full='Development of a Post-Radiation “Safety Net”: A Machine Learning Approach to Predicting Severe Adverse Events Using the SEER Database', status='ASTRO Annual Meeting 2026 · abstract', kind='paper',
  authors='<b>A. Parsaee</b>, K. G. Samuel, N. Mohan, P. Wong', note='First author',
  links=[('Read the abstract', 'https://doi.org/10.1016/j.ijrobp.2026.06.1229')], question='Predicting severe adverse events from clinical records.',
  point='Registry data can train a sensitive screening model that flags most patients at risk of early death after radiation therapy, so they get closer monitoring.',
  problem='Severe complications after radiation therapy need early attention, and value-based care programs need a way to prioritize monitoring. Early mortality within three months serves as a proxy for severe acute adverse events.',
  did='We analysed 235,035 patients treated with radiation in the US SEER database (2010–2022), using nine patient-reportable variables across medical, socioeconomic and metadata domains. We compared classifiers and Cox survival models, and a global model against site-specific models for lung, breast and prostate cancer.',
  found=['Early mortality affected 4% of patients. A gradient boosting classifier flagged 92% of them (recall 0.92) at precision 0.10, an acceptable trade-off for a safety net.', 'The global Cox model reached a C-index of 0.80; within individual sites it averaged 0.76, and site-specific models recovered 0.78.', 'Age, income and marital status were significant independent predictors.'],
  caption='Simulated patients, tuned so the operating point matches the paper’s recall and precision.',
  deeper='Next steps are Statistics Canada data with actual radiation-related adverse events, richer socioeconomic features, and multicentre validation on independent records before clinical use.'),
 dict(id='robot', num='21', fam='other', famlabel='Origins & explorations', title='Learning on a real robot',
  full='Synchronous vs Asynchronous Reinforcement Learning in a Real World Robot', status='Preprint · arXiv 2025 · presented at RISE', kind='paper',
  authors='<b>Ali Parsaee</b>, Fahim Shahriar, C. He, R. Tan', note='All authors contributed equally',
  links=[('Read the paper (arXiv)', 'https://arxiv.org/abs/2503.14554')], question='How does the timing of learning and action matter?',
  point='A robot that stops to learn falls behind a changing world. Learning in parallel with acting gave faster learning and more reward, even with fewer learning updates.',
  problem='Reinforcement learning agents improve through expensive gradient updates. In simulation the world waits for them; a physical robot’s environment does not.',
  did='We compared synchronous and asynchronous learning on a Franka Emika Panda arm in a visual reaching task: 25 runs for each of four settings, 100 runs and about 200 hours of robot time.',
  found=['Asynchronous agents learned faster and earned significantly more reward.', 'Faster response time beat a larger number of gradient updates: the asynchronous high-resolution agent made fewer updates and still did better.'],
  caption='Simulated reaching task. The findings quoted are from the robot experiments.',
  deeper='Because rewards cannot be observed continuously, reward was set in proportion to the length of the action cycle, so agents that act more often are not unfairly favoured.'),
 dict(id='biology', num='23', fam='other', famlabel='Origins & explorations', title='Where I started: biology',
  full='Polyherbal and Multimodal Treatments: Kaempferol- and Quercetin-Rich Herbs Alleviate Symptoms of Alzheimer’s Disease', status='Biology · 2023', kind='paper',
  authors='C. Alexander, <b>A. Parsaee</b>, M. Vasefi', note='',
  links=[('Read the paper', 'https://www.mdpi.com/2079-7737/12/11/1453')], question='Bringing scattered biological evidence together.',
  point='Alzheimer’s disease has many interacting causes, so a treatment that acts on several of them at once may help more than a single-target drug.',
  problem='Alzheimer’s disease involves plaques, tangles, inflammation, oxidative stress and damaged neuroplasticity. Current treatments are limited, and the evidence on herbal alternatives was scattered across many small studies.',
  did='We followed PRISMA guidelines to identify herbal treatments, their active compounds and their likely mechanisms, then organized the findings into one mechanistic picture.',
  found=['Common herbs, including Ginkgo biloba, Camellia sinensis, Glycyrrhiza uralensis, Cyperus rotundus and Bupleurum falcatum, gave promising pre-clinical results.', 'These herbs are rich in the flavonoids kaempferol and quercetin, which act on several mechanisms at once.', 'We proposed that a kaempferol- and quercetin-rich herbal mix could treat Alzheimer’s-related brain damage.'],
  caption='Map of the connections described in the review.', deeper='The evidence for kaempferol was much thinner than for quercetin, so its proposed mechanisms rest partly on what is known about quercetin. That is a hypothesis for future studies, not an established result.'),
]
